<?php if($delivery===[]):?><div class="ai-platform__empty">예약 발신 내역이 없습니다.</div><?php else:?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>회사</th><th>채널</th><th>예약</th><th>일정/단말</th><th>FCM outbox</th><th>시도</th></tr></thead><tbody><?php foreach($delivery as $item):$deviceState=(string)($item['device_status']?:$item['schedule_status']);$outbox=(string)$item['outbox_status'];?><tr><td><strong><?=htmlspecialchars((string)$item['company_name'])?></strong><small class="d-block text-muted ai-platform__mono"><?=htmlspecialchars($short((string)$item['company_id']))?></small></td><td><?=htmlspecialchars((string)$item['channel'])?></td><td><?=$date((string)$item['scheduled_at'])?></td><td><span class="badge text-bg-<?=$badge($deviceState)?>"><?=htmlspecialchars($statusLabels[$deviceState]??$deviceState)?></span></td><td><span class="badge text-bg-<?=$badge($outbox)?>"><?=htmlspecialchars($statusLabels[$outbox]??$outbox)?></span></td><td><?=number_format((int)$item['attempt_count'])?>회</td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
